def solve_case(case):
    coins = case.get('coins', [])
    amount = case.get('amount', 0)
    if amount == 0:
        return 0
    uniq = list(set(coins))
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in uniq:
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return -1 if dp[amount] > amount else dp[amount)

