def solve_case(case):
    s = case.get("s", "")
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    left = {'(', '[', '{'}
    for ch in s:
        if ch in left:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

