def solve_case(case):
    nums = case.get('nums', [])
    if not nums:
        return 0
    tails = []
    for x in nums:
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid
        if left == len(tails):
            tails.append(x)
        else:
            tails[left] = x
    return len(tails)

